45	/**
46	 * Python's datetime.datetime. `tzOffsetMinutes` is null for a naive value, or
47	 * the UTC offset in minutes for an aware one.
48	 */
49	export class PyDateTime {
50	  constructor(year, month, day, hour, minute, second, microsecond, tzOffsetMinutes = null) {
51	    this.year = year;
52	    this.month = month;
53	    this.day = day;
54	    this.hour = hour;
55	    this.minute = minute;
56	    this.second = second;
57	    this.microsecond = microsecond;
58	    this.tzOffsetMinutes = tzOffsetMinutes;
59	  }
60	
61	  /** datetime.isoformat(sep) — the form PyYAML's representer emits. */
62	  isoformat(sep = 'T') {
63	    let out = `${pad(this.year, 4)}-${pad(this.month, 2)}-${pad(this.day, 2)}${sep}` +
64	      `${pad(this.hour, 2)}:${pad(this.minute, 2)}:${pad(this.second, 2)}`;
65	    if (this.microsecond) out += '.' + pad(this.microsecond, 6);
66	    if (this.tzOffsetMinutes !== null) {
67	      const sign = this.tzOffsetMinutes < 0 ? '-' : '+';
68	      const abs = Math.abs(this.tzOffsetMinutes);
69	      out += `${sign}${pad(Math.floor(abs / 60), 2)}:${pad(abs % 60, 2)}`;
70	    }
71	    return out;
72	  }
73	}
74	
75	function pad(n, width) {
76	  let s = String(n);
77	  while (s.length < width) s = '0' + s;
78	  return s;
79	}
