81	/**
82	 * Canonical key for Python hash/equality semantics: `1`, `1.0` and `True`
83	 * all collide, as they do in a real dict. Throws for unhashable values.
84	 */
85	export function pyKey(value) {
86	  if (value === null) return 'N';
87	  if (value === true) return 'i1';
88	  if (value === false) return 'i0';
89	  if (typeof value === 'bigint') return 'i' + value.toString();
90	  if (typeof value === 'number') {
91	    if (Number.isFinite(value) && Number.isInteger(value)) return 'i' + BigInt(value).toString();
92	    if (Number.isNaN(value)) return 'fnan';
93	    return 'f' + String(value);
94	  }
95	  if (typeof value === 'string') return 's' + value;
96	  if (value instanceof PyBytes) {
97	    let s = 'b';
98	    for (const b of value.bytes) s += ',' + b;
99	    return s;
100	  }
101	  if (value instanceof PyTuple) {
102	    const parts = value.items.map((item) => pyKey(item).length + ':' + pyKey(item));
103	    return 't(' + parts.join(',') + ')';
104	  }
105	  if (value instanceof PyDate) return 'D' + value.isoformat();
106	  if (value instanceof PyDateTime) return 'T' + value.isoformat();
107	  throw new PyTypeError(`unhashable type: '${pyTypeName(value)}'`);
108	}
109	
110	export function pyTypeName(value) {
111	  if (value === null) return 'NoneType';
112	  if (typeof value === 'boolean') return 'bool';
113	  if (typeof value === 'bigint') return 'int';
114	  if (typeof value === 'number') return 'float';
115	  if (typeof value === 'string') return 'str';
116	  if (Array.isArray(value)) return 'list';
117	  if (value instanceof PyBytes) return 'bytes';
118	  if (value instanceof PyTuple) return 'tuple';
119	  if (value instanceof PySet) return 'set';
120	  if (value instanceof PyDict) return 'dict';
121	  if (value instanceof PyDate) return 'date';
122	  if (value instanceof PyDateTime) return 'datetime';
123	  return 'object';
124	}
