126	/** Insertion-ordered dict with Python key equality. */
127	export class PyDict {
128	  constructor() {
129	    this.map = new Map(); // canonical key -> [key, value]
130	  }
131	
132	  get size() {
133	    return this.map.size;
134	  }
135	
136	  set(key, value) {
137	    const k = pyKey(key);
138	    const existing = this.map.get(k);
139	    // Python keeps the *original* key object when a later assignment collides.
140	    if (existing !== undefined) existing[1] = value;
141	    else this.map.set(k, [key, value]);
142	  }
143	
144	  get(key) {
145	    const entry = this.map.get(pyKey(key));
146	    return entry === undefined ? undefined : entry[1];
147	  }
148	
149	  has(key) {
150	    return this.map.has(pyKey(key));
151	  }
152	
153	  /** [key, value] pairs in insertion order. */
154	  items() {
155	    return [...this.map.values()].map(([k, v]) => [k, v]);
156	  }
157	
158	  keys() {
159	    return [...this.map.values()].map(([k]) => k);
160	  }
161	
162	  /** dict.update(other) */
163	  update(other) {
164	    for (const [k, v] of other.items()) this.set(k, v);
165	  }
166	}
