168	/** Insertion-ordered set with Python key equality. */
169	export class PySet {
170	  constructor(items = []) {
171	    this.map = new Map();
172	    for (const item of items) this.add(item);
173	  }
174	
175	  get size() {
176	    return this.map.size;
177	  }
178	
179	  add(item) {
180	    const k = pyKey(item);
181	    if (!this.map.has(k)) this.map.set(k, item);
182	  }
183	
184	  has(item) {
185	    return this.map.has(pyKey(item));
186	  }
187	
188	  values() {
189	    return [...this.map.values()];
190	  }
191	}
