197	/**
198	 * CPython's repr() for a finite float: shortest round-tripping digits, laid out
199	 * as fixed-point when -4 < decimal-point <= 16 and scientific otherwise, always
200	 * with a fractional part in fixed-point form.
201	 */
202	export function pyReprFloat(value) {
203	  if (Number.isNaN(value)) return 'nan';
204	  if (value === Infinity) return 'inf';
205	  if (value === -Infinity) return '-inf';
206	
207	  const negative = value < 0 || (value === 0 && 1 / value < 0);
208	  const abs = Math.abs(value);
209	  const sign = negative ? '-' : '';
210	
211	  if (abs === 0) return sign + '0.0';
212	
213	  // toExponential() with no argument yields the shortest digit string that
214	  // uniquely identifies the double — exactly what CPython's mode-0 dtoa gives.
215	  const exp = abs.toExponential();
216	  const eIndex = exp.indexOf('e');
217	  const mantissa = exp.slice(0, eIndex);
218	  const exponent = Number(exp.slice(eIndex + 1));
219	  const digits = mantissa.replace('.', '');
220	  // Position of the decimal point relative to the digit string.
221	  const decpt = exponent + 1;
222	
223	  if (decpt > 16 || decpt < -3) {
224	    let out = digits[0];
225	    if (digits.length > 1) out += '.' + digits.slice(1);
226	    const e = decpt - 1;
227	    const esign = e < 0 ? '-' : '+';
228	    out += 'e' + esign + pad(Math.abs(e), 2);
229	    return sign + out;
230	  }
231	
232	  if (decpt <= 0) return sign + '0.' + '0'.repeat(-decpt) + digits;
233	  if (decpt >= digits.length) {
234	    return sign + digits + '0'.repeat(decpt - digits.length) + '.0';
235	  }
236	  return sign + digits.slice(0, decpt) + '.' + digits.slice(decpt);
237	}
