239	// ---------------------------------------------------------------------------
240	// Python comparison, used by the representer's `sorted(mapping.items())`
241	// ---------------------------------------------------------------------------
242	
243	const NUMERIC = 1;
244	const STRING = 2;
245	const BYTES = 3;
246	const SEQUENCE = 4;
247	const DATE = 5;
248	const DATETIME = 6;
249	const UNORDERABLE = 0;
250	
251	function orderClass(v) {
252	  if (typeof v === 'boolean' || typeof v === 'bigint' || typeof v === 'number') return NUMERIC;
253	  if (typeof v === 'string') return STRING;
254	  if (v instanceof PyBytes) return BYTES;
255	  if (Array.isArray(v) || v instanceof PyTuple) return SEQUENCE;
256	  if (v instanceof PyDate) return DATE;
257	  if (v instanceof PyDateTime) return DATETIME;
258	  return UNORDERABLE;
259	}
260	
261	function toNumber(v) {
262	  if (typeof v === 'boolean') return v ? 1 : 0;
263	  if (typeof v === 'bigint') return v;
264	  return v;
265	}
266	
267	/** Python's `a < b`, raising PyTypeError where Python raises TypeError. */
268	export function pyLessThan(a, b) {
269	  const ca = orderClass(a);
270	  const cb = orderClass(b);
271	  if (ca === UNORDERABLE || cb === UNORDERABLE || ca !== cb) {
272	    throw new PyTypeError(
273	      `'<' not supported between instances of '${pyTypeName(a)}' and '${pyTypeName(b)}'`);
274	  }
275	  switch (ca) {
276	    case NUMERIC: {
277	      const na = toNumber(a);
278	      const nb = toNumber(b);
279	      if (typeof na === 'bigint' && typeof nb === 'bigint') return na < nb;
280	      return Number(na) < Number(nb);
281	    }
282	    case STRING:
283	      return codePointLess(a, b);
284	    case BYTES:
285	      return bytesLess(a.bytes, b.bytes);
286	    case SEQUENCE: {
287	      // list and tuple are not mutually comparable in Python.
288	      const aIsTuple = a instanceof PyTuple;
289	      const bIsTuple = b instanceof PyTuple;
290	      if (aIsTuple !== bIsTuple) {
291	        throw new PyTypeError(
292	          `'<' not supported between instances of '${pyTypeName(a)}' and '${pyTypeName(b)}'`);
293	      }
294	      const xs = aIsTuple ? a.items : a;
295	      const ys = bIsTuple ? b.items : b;
296	      const n = Math.min(xs.length, ys.length);
297	      for (let i = 0; i < n; i++) {
298	        if (!pyEquals(xs[i], ys[i])) return pyLessThan(xs[i], ys[i]);
299	      }
300	      return xs.length < ys.length;
301	    }
302	    case DATE:
303	      return a.isoformat() < b.isoformat();
304	    case DATETIME:
305	      return compareDateTime(a, b) < 0;
306	    default:
307	      throw new PyTypeError('unorderable');
308	  }
309	}
310	
311	/** Compare two strings by code point, the way Python compares str. */
312	function codePointLess(a, b) {
313	  const as = [...a];
314	  const bs = [...b];
315	  const n = Math.min(as.length, bs.length);
316	  for (let i = 0; i < n; i++) {
317	    const x = as[i].codePointAt(0);
318	    const y = bs[i].codePointAt(0);
319	    if (x !== y) return x < y;
320	  }
321	  return as.length < bs.length;
322	}
323	
324	function bytesLess(a, b) {
325	  const n = Math.min(a.length, b.length);
326	  for (let i = 0; i < n; i++) {
327	    if (a[i] !== b[i]) return a[i] < b[i];
328	  }
329	  return a.length < b.length;
330	}
331	
332	function compareDateTime(a, b) {
333	  // Aware and naive datetimes cannot be ordered against each other.
334	  if ((a.tzOffsetMinutes === null) !== (b.tzOffsetMinutes === null)) {
335	    throw new PyTypeError("can't compare offset-naive and offset-aware datetimes");
336	  }
337	  const ka = dateTimeSortKey(a);
338	  const kb = dateTimeSortKey(b);
339	  for (let i = 0; i < ka.length; i++) {
340	    if (ka[i] !== kb[i]) return ka[i] < kb[i] ? -1 : 1;
341	  }
342	  return 0;
343	}
344	
345	function dateTimeSortKey(d) {
346	  const offset = d.tzOffsetMinutes === null ? 0 : d.tzOffsetMinutes;
347	  const days = daysFromCivil(d.year, d.month, d.day);
348	  const minutes = days * 1440 + d.hour * 60 + d.minute - offset;
349	  return [minutes, d.second, d.microsecond];
350	}
351	
352	function daysFromCivil(y, m, d) {
353	  const yy = m <= 2 ? y - 1 : y;
354	  const era = Math.floor(yy / 400);
355	  const yoe = yy - era * 400;
356	  const mp = (m + 9) % 12;
357	  const doy = Math.floor((153 * mp + 2) / 5) + d - 1;
358	  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
359	  return era * 146097 + doe - 719468;
360	}
361	
362	/** Python's `a == b` for the value types we can produce. */
363	export function pyEquals(a, b) {
364	  const ca = orderClass(a);
365	  const cb = orderClass(b);
366	  if (a === null || b === null) return a === b;
367	  if (ca !== cb || ca === UNORDERABLE) {
368	    // Different families compare unequal rather than raising.
369	    if (ca === UNORDERABLE || cb === UNORDERABLE) {
370	      try {
371	        return pyKey(a) === pyKey(b);
372	      } catch {
373	        return a === b;
374	      }
375	    }
376	    return false;
377	  }
378	  try {
379	    return !pyLessThan(a, b) && !pyLessThan(b, a);
380	  } catch {
381	    return false;
382	  }
383	}
