385	/**
386	 * CPython list.sort() for short lists: detect the initial run, reverse it if
387	 * descending, then binary-insertion-sort the remainder. Reproducing the real
388	 * comparison sequence matters because a TypeError from any single comparison is
389	 * what makes PyYAML fall back to insertion order.
390	 */
391	export function pySortInPlace(items, less) {
392	  const n = items.length;
393	  if (n < 2) return items;
394	
395	  // count_run
396	  let runEnd = 2;
397	  let descending = false;
398	  if (less(items[1], items[0])) {
399	    descending = true;
400	    while (runEnd < n && less(items[runEnd], items[runEnd - 1])) runEnd++;
401	    // Reverse the strictly-descending prefix in place.
402	    for (let lo = 0, hi = runEnd - 1; lo < hi; lo++, hi--) {
403	      const t = items[lo];
404	      items[lo] = items[hi];
405	      items[hi] = t;
406	    }
407	  } else {
408	    while (runEnd < n && !less(items[runEnd], items[runEnd - 1])) runEnd++;
409	  }
410	  void descending;
411	
412	  // binarysort: extend the sorted prefix one element at a time.
413	  for (let i = runEnd; i < n; i++) {
414	    const pivot = items[i];
415	    let lo = 0;
416	    let hi = i;
417	    while (lo < hi) {
418	      const mid = (lo + hi) >>> 1;
419	      if (less(pivot, items[mid])) hi = mid;
420	      else lo = mid + 1;
421	    }
422	    for (let j = i; j > lo; j--) items[j] = items[j - 1];
423	    items[lo] = pivot;
424	  }
425	  return items;
426	}
