429	// base64, matching Python's base64 module
430	// ---------------------------------------------------------------------------
431	
432	const B64_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
433	
434	/** base64.encodebytes(): wrapped at 76 characters, trailing newline. */
435	export function encodeBase64Wrapped(bytes) {
436	  let raw = '';
437	  for (let i = 0; i < bytes.length; i += 3) {
438	    const b0 = bytes[i];
439	    const b1 = i + 1 < bytes.length ? bytes[i + 1] : 0;
440	    const b2 = i + 2 < bytes.length ? bytes[i + 2] : 0;
441	    raw += B64_ALPHABET[b0 >> 2];
442	    raw += B64_ALPHABET[((b0 & 0x03) << 4) | (b1 >> 4)];
443	    raw += i + 1 < bytes.length ? B64_ALPHABET[((b1 & 0x0f) << 2) | (b2 >> 6)] : '=';
444	    raw += i + 2 < bytes.length ? B64_ALPHABET[b2 & 0x3f] : '=';
445	  }
446	  let out = '';
447	  for (let i = 0; i < raw.length; i += 76) out += raw.slice(i, i + 76) + '\n';
448	  if (raw.length === 0) out = '';
449	  return out;
450	}
451	
452	/**
453	 * binascii.a2b_base64(): skip characters outside the alphabet, stop at padding,
454	 * and raise on a truncated final group.
455	 */
456	export function decodeBase64(text) {
457	  const values = [];
458	  for (const ch of text) {
459	    if (ch === '=') break;
460	    const idx = B64_ALPHABET.indexOf(ch);
461	    if (idx >= 0) values.push(idx);
462	  }
463	  if (values.length % 4 === 1) {
464	    const err = new Error('Invalid base64-encoded string: number of data characters (' +
465	      values.length + ') cannot be 1 more than a multiple of 4');
466	    err.qualifiedName = 'binascii.Error';
467	    throw err;
468	  }
469	  const out = [];
470	  for (let i = 0; i + 1 < values.length; i += 4) {
471	    const n = values.length - i;
472	    out.push(((values[i] << 2) | (values[i + 1] >> 4)) & 0xff);
473	    if (n >= 3) out.push(((values[i + 1] << 4) | (values[i + 2] >> 2)) & 0xff);
474	    if (n >= 4) out.push(((values[i + 2] << 6) | values[i + 3]) & 0xff);
475	  }
476	  return new Uint8Array(out);
477	}
