// Port of PyYAML's serializer.py.
//
// Composition note: PyYAML's `Serializer.__init__` takes keyword arguments that
// `Dumper.__init__` forwards. Here the mixin constructor receives whatever
// `new Dumper(stream, options)` was called with; the options bag is the first
// object-valued argument after the stream.

import { SerializerError } from './errors.mjs';
import {
  StreamStartEvent, StreamEndEvent, DocumentStartEvent, DocumentEndEvent,
  AliasEvent, ScalarEvent, SequenceStartEvent, SequenceEndEvent,
  MappingStartEvent, MappingEndEvent,
} from './events.mjs';
import { ScalarNode, SequenceNode, MappingNode } from './nodes.mjs';

function dumperOptions(args) {
  for (let i = 1; i < args.length; i++) {
    if (args[i] !== null && typeof args[i] === 'object') return args[i];
  }
  return {};
}

/** Python's `'id%03d' % n`. */
function formatAnchor(template, n) {
  const at = template.indexOf('%03d');
  if (at < 0) return template;
  let digits = String(n);
  while (digits.length < 3) digits = '0' + digits;
  return template.slice(0, at) + digits + template.slice(at + 4);
}

export const SerializerMixin = (Base) => {
  class Serializer extends Base {
    constructor(...args) {
      super(...args);
      const options = dumperOptions(args);
      this.useEncoding = options.encoding ?? null;
      this.useExplicitStart = options.explicitStart ?? null;
      this.useExplicitEnd = options.explicitEnd ?? null;
      this.useVersion = options.version ?? null;
      this.useTags = options.tags ?? null;
      // Python dicts keyed by node identity -> JS Maps keyed by the node object.
      this.serializedNodes = new Map();
      this.anchors = new Map();
      this.lastAnchorId = 0;
      this.closed = null;
    }

    open() {
      if (this.closed === null) {
        this.emit(new StreamStartEvent(null, null, this.useEncoding));
        this.closed = false;
      } else if (this.closed) {
        throw new SerializerError('serializer is closed');
      } else {
        throw new SerializerError('serializer is already opened');
      }
    }

    close() {
      if (this.closed === null) {
        throw new SerializerError('serializer is not opened');
      } else if (!this.closed) {
        this.emit(new StreamEndEvent());
        this.closed = true;
      }
    }

    serialize(node) {
      if (this.closed === null) {
        throw new SerializerError('serializer is not opened');
      } else if (this.closed) {
        throw new SerializerError('serializer is closed');
      }
      this.emit(new DocumentStartEvent(
        null, null, this.useExplicitStart, this.useVersion, this.useTags));
      this.anchorNode(node);
      this.serializeNode(node, null, null);
      this.emit(new DocumentEndEvent(null, null, this.useExplicitEnd));
      this.serializedNodes = new Map();
      this.anchors = new Map();
      this.lastAnchorId = 0;
    }

    // Two passes in one walk: a node is entered with a null anchor, and only
    // earns a generated anchor when it is reached a second time. Anchor ids are
    // therefore handed out in *second*-encounter order.
    anchorNode(node) {
      if (this.anchors.has(node)) {
        if (this.anchors.get(node) === null) {
          this.anchors.set(node, this.generateAnchor(node));
        }
      } else {
        this.anchors.set(node, null);
        if (node instanceof SequenceNode) {
          for (const item of node.value) this.anchorNode(item);
        } else if (node instanceof MappingNode) {
          for (const [key, value] of node.value) {
            this.anchorNode(key);
            this.anchorNode(value);
          }
        }
      }
    }

    generateAnchor(node) {
      void node;
      this.lastAnchorId += 1;
      return formatAnchor(this.ANCHOR_TEMPLATE, this.lastAnchorId);
    }

    serializeNode(node, parent, index) {
      const alias = this.anchors.get(node);
      if (this.serializedNodes.has(node)) {
        this.emit(new AliasEvent(alias));
      } else {
        this.serializedNodes.set(node, true);
        this.descendResolver(parent, index);
        if (node instanceof ScalarNode) {
          const detectedTag = this.resolve(ScalarNode, node.value, [true, false]);
          const defaultTag = this.resolve(ScalarNode, node.value, [false, true]);
          const implicit = [node.tag === detectedTag, node.tag === defaultTag];
          this.emit(new ScalarEvent(
            alias, node.tag, implicit, node.value, null, null, node.style));
        } else if (node instanceof SequenceNode) {
          const implicit = node.tag === this.resolve(SequenceNode, node.value, true);
          this.emit(new SequenceStartEvent(
            alias, node.tag, implicit, null, null, node.flowStyle));
          let i = 0;
          for (const item of node.value) {
            this.serializeNode(item, node, i);
            i += 1;
          }
          this.emit(new SequenceEndEvent());
        } else if (node instanceof MappingNode) {
          const implicit = node.tag === this.resolve(MappingNode, node.value, true);
          this.emit(new MappingStartEvent(
            alias, node.tag, implicit, null, null, node.flowStyle));
          for (const [key, value] of node.value) {
            this.serializeNode(key, node, null);
            this.serializeNode(value, node, key);
          }
          this.emit(new MappingEndEvent());
        }
        this.ascendResolver();
      }
      void index;
    }
  }

  Serializer.prototype.ANCHOR_TEMPLATE = 'id%03d';
  return Serializer;
};

// Port of PyYAML's representer.py — BaseRepresenter, SafeRepresenter and the
// extra Representer entries that the full Dumper adds (notably python/tuple).
//
// PyYAML dispatches on `type(data).__mro__` against class-level dicts. Here the
// registries are module-level Maps keyed by the Python type *name* that
// `pyTypeName` reports, and `pyMro` supplies the (short) method resolution
// orders that matter: bool -> int, datetime -> date.
//
// `id(data)` becomes the data object itself: a JS Map keys on object identity,
// which is exactly what CPython's id() based alias key gives us.

import { RepresenterError, PyTypeError } from './errors.mjs';
import { ScalarNode, SequenceNode, MappingNode } from './nodes.mjs';
import {
  PyBytes, PyTuple, PyDict, PySet,
  pyTypeName, pyReprFloat, pyLessThan, pySortInPlace, encodeBase64Wrapped,
} from './pytypes.mjs';

const yamlRepresenters = new Map();
const yamlMultiRepresenters = new Map();

function addRepresenter(dataType, representer) {
  yamlRepresenters.set(dataType, representer);
}

function addMultiRepresenter(dataType, representer) {
  yamlMultiRepresenters.set(dataType, representer);
}

/** The prefix of `type(data).__mro__` that the registries can match on. */
function pyMro(data) {
  const name = pyTypeName(data);
  if (name === 'bool') return ['bool', 'int', 'object'];
  if (name === 'datetime') return ['datetime', 'date', 'object'];
  return [name, 'object'];
}

/** Python `for item in sequence` over the sequence types we can be handed. */
function iterate(sequence) {
  if (sequence instanceof PyTuple) return sequence.items;
  if (sequence instanceof PySet) return sequence.values();
  return sequence;
}

/** Python `hasattr(mapping, 'items')`. */
function hasItems(mapping) {
  return mapping !== null && typeof mapping === 'object' &&
    typeof mapping.items === 'function';
}

function dumperOptions(args) {
  for (let i = 1; i < args.length; i++) {
    if (args[i] !== null && typeof args[i] === 'object') return args[i];
  }
  return {};
}

export const RepresenterMixin = (Base) => {
  class Representer extends Base {
    constructor(...args) {
      super(...args);
      const options = dumperOptions(args);
      this.defaultStyle = options.defaultStyle ?? null;
      this.sortKeys = options.sortKeys ?? true;
      this.defaultFlowStyle = options.defaultFlowStyle ?? false;
      this.representedObjects = new Map();
      this.objectKeeper = [];
      this.aliasKey = null;
    }

    // ---------------------------------------------------------------- Base

    represent(data) {
      const node = this.representData(data);
      this.serialize(node);
      this.representedObjects = new Map();
      this.objectKeeper = [];
      this.aliasKey = null;
    }

    representData(data) {
      if (this.ignoreAliases(data)) this.aliasKey = null;
      else this.aliasKey = data;
      if (this.aliasKey !== null) {
        if (this.representedObjects.has(this.aliasKey)) {
          return this.representedObjects.get(this.aliasKey);
        }
        this.objectKeeper.push(data);
      }
      const dataTypes = pyMro(data);
      let node;
      if (yamlRepresenters.has(dataTypes[0])) {
        node = yamlRepresenters.get(dataTypes[0])(this, data);
      } else {
        let matched = false;
        for (const dataType of dataTypes) {
          if (yamlMultiRepresenters.has(dataType)) {
            node = yamlMultiRepresenters.get(dataType)(this, data);
            matched = true;
            break;
          }
        }
        if (!matched) {
          if (yamlMultiRepresenters.has(null)) {
            node = yamlMultiRepresenters.get(null)(this, data);
          } else if (yamlRepresenters.has(null)) {
            node = yamlRepresenters.get(null)(this, data);
          } else {
            node = new ScalarNode(null, String(data));
          }
        }
      }
      return node;
    }

    representKey(data) {
      return this.representData(data);
    }

    representScalar(tag, value, style = null) {
      if (style === null) style = this.defaultStyle;
      const node = new ScalarNode(tag, value, null, null, style);
      if (this.aliasKey !== null) this.representedObjects.set(this.aliasKey, node);
      return node;
    }

    representSequence(tag, sequence, flowStyle = null) {
      const value = [];
      const node = new SequenceNode(tag, value, null, null, flowStyle);
      if (this.aliasKey !== null) this.representedObjects.set(this.aliasKey, node);
      let bestStyle = true;
      for (const item of iterate(sequence)) {
        const nodeItem = this.representData(item);
        if (!(nodeItem instanceof ScalarNode && !nodeItem.style)) bestStyle = false;
        value.push(nodeItem);
      }
      if (flowStyle === null) {
        if (this.defaultFlowStyle !== null) node.flowStyle = this.defaultFlowStyle;
        else node.flowStyle = bestStyle;
      }
      return node;
    }

    representMapping(tag, mapping, flowStyle = null) {
      const value = [];
      const node = new MappingNode(tag, value, null, null, flowStyle);
      if (this.aliasKey !== null) this.representedObjects.set(this.aliasKey, node);
      let bestStyle = true;
      if (hasItems(mapping)) {
        mapping = mapping.items();
        if (this.sortKeys) {
          // `mapping = sorted(mapping)` — sorted() builds a new list, so a
          // TypeError from any single comparison leaves the insertion order
          // untouched. Hence the sort happens on a copy.
          try {
            const ordered = mapping.slice();
            pySortInPlace(ordered, (a, b) => pyLessThan(a, b));
            mapping = ordered;
          } catch (err) {
            if (!(err instanceof PyTypeError)) throw err;
          }
        }
      }
      for (const [itemKey, itemValue] of mapping) {
        const nodeKey = this.representKey(itemKey);
        const nodeValue = this.representData(itemValue);
        if (!(nodeKey instanceof ScalarNode && !nodeKey.style)) bestStyle = false;
        if (!(nodeValue instanceof ScalarNode && !nodeValue.style)) bestStyle = false;
        value.push([nodeKey, nodeValue]);
      }
      if (flowStyle === null) {
        if (this.defaultFlowStyle !== null) node.flowStyle = this.defaultFlowStyle;
        else node.flowStyle = bestStyle;
      }
      return node;
    }

    // ---------------------------------------------------------------- Safe

    ignoreAliases(data) {
      if (data === null) return true;
      if (data instanceof PyTuple && data.items.length === 0) return true;
      if (typeof data === 'string' || data instanceof PyBytes ||
        typeof data === 'boolean' || typeof data === 'bigint' ||
        typeof data === 'number') return true;
      // falls off the end -> None, which is falsy, as in PyYAML
    }

    representNone(data) {
      return this.representScalar('tag:yaml.org,2002:null', 'null');
    }

    representStr(data) {
      return this.representScalar('tag:yaml.org,2002:str', data);
    }

    representBinary(data) {
      const text = encodeBase64Wrapped(data.bytes);
      return this.representScalar('tag:yaml.org,2002:binary', text, '|');
    }

    representBool(data) {
      const value = data ? 'true' : 'false';
      return this.representScalar('tag:yaml.org,2002:bool', value);
    }

    representInt(data) {
      return this.representScalar('tag:yaml.org,2002:int', data.toString());
    }

    representFloat(data) {
      let value;
      if (data !== data) {
        value = '.nan';
      } else if (data === Infinity) {
        value = '.inf';
      } else if (data === -Infinity) {
        value = '-.inf';
      } else {
        value = pyReprFloat(data).toLowerCase();
        // repr() can drop the fractional part (repr(1e17) == '1e+17'), which is
        // not a valid !!float; put '.0' back in front of the exponent.
        if (!value.includes('.') && value.includes('e')) {
          value = value.replace('e', '.0e');
        }
      }
      return this.representScalar('tag:yaml.org,2002:float', value);
    }

    representList(data) {
      return this.representSequence('tag:yaml.org,2002:seq', data);
    }

    representDict(data) {
      return this.representMapping('tag:yaml.org,2002:map', data);
    }

    representSet(data) {
      const value = new PyDict();
      for (const key of data.values()) value.set(key, null);
      return this.representMapping('tag:yaml.org,2002:set', value);
    }

    representDate(data) {
      const value = data.isoformat();
      return this.representScalar('tag:yaml.org,2002:timestamp', value);
    }

    representDateTime(data) {
      const value = data.isoformat(' ');
      return this.representScalar('tag:yaml.org,2002:timestamp', value);
    }

    representUndefined(data) {
      throw new RepresenterError('cannot represent an object');
    }

    // ----------------------------------------------------- full Representer

    representTuple(data) {
      return this.representSequence('tag:yaml.org,2002:python/tuple', data);
    }

    // Stands in for PyYAML's copyreg-driven represent_object, registered as the
    // `object` multi-representer. Nothing safe_load can produce reaches it, and
    // an arbitrary reduce protocol has no JS analogue, so it raises the same
    // error represent_undefined would.
    representObject(data) {
      throw new RepresenterError('cannot represent an object');
    }
  }

  Representer.prototype.yamlRepresenters = yamlRepresenters;
  Representer.prototype.yamlMultiRepresenters = yamlMultiRepresenters;
  return Representer;
};

// SafeRepresenter.add_representer(...) block, in source order.
addRepresenter('NoneType', (self, data) => self.representNone(data));
addRepresenter('str', (self, data) => self.representStr(data));
addRepresenter('bytes', (self, data) => self.representBinary(data));
addRepresenter('bool', (self, data) => self.representBool(data));
addRepresenter('int', (self, data) => self.representInt(data));
addRepresenter('float', (self, data) => self.representFloat(data));
addRepresenter('list', (self, data) => self.representList(data));
addRepresenter('tuple', (self, data) => self.representList(data));
addRepresenter('dict', (self, data) => self.representDict(data));
addRepresenter('set', (self, data) => self.representSet(data));
addRepresenter('date', (self, data) => self.representDate(data));
addRepresenter('datetime', (self, data) => self.representDateTime(data));
