// Representer.add_representer(...) block — the full Dumper's overrides. The
// complex / name / module / OrderedDict entries have no reachable counterpart
// here (safe_load cannot build those values) and are omitted.
addRepresenter('tuple', (self, data) => self.representTuple(data));
addMultiRepresenter('object', (self, data) => self.representObject(data));

